import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import kotlin.random.Random

// 模拟一个从网络获取用户数据的挂起函数
suspend fun fetchUserProfileFromNetwork(userId: Int): String {
    delay(1000) // 模拟网络延迟
    if (Random.nextFloat() < 0.3f) { // 30%的模拟失败率
        throw RuntimeException("Network error for user $userId")
    }
    return "User_$userId_Data: ${Random.nextInt()}"
}

// 创建一个发射用户数据的 Flow
fun getUserProfileFlow(userId: Int): Flow<String> = flow {
    println("Flow started on thread: ${Thread.currentThread().name}")
    val rawData = fetchUserProfileFromNetwork(userId)
    emit(rawData) // 发射原始数据
    val processedData = rawData.uppercase() // 简单处理
    emit(processedData) // 发射处理后的数据
}.flowOn(Dispatchers.IO) // 指定上游（数据生产）在IO线程执行

fun main() = runBlocking {
    println("Collecting on thread: ${Thread.currentThread().name}")

    getUserProfileFlow(42)
        .catch { e -> // 捕获上游异常
            println("Caught error: ${e.message}")
            emit("Default_Fallback_Data") // 发射备用数据
        }
        .onCompletion { cause -> // 完成时（无论成功或失败）
            println("Flow completed. Cause: ${cause?.message ?: "Success"}")
        }
        .collect { data -> // 开始收集
            println("Received on ${Thread.currentThread().name}: $data")
        }
}

